CREATE COLUMN TABLE "TEST_AP"."OCQG" ("GroupCode" SMALLINT CS_INT NOT NULL , "GroupName" NVARCHAR(50) NOT NULL , "UserSign" SMALLINT CS_INT, "Filler" NVARCHAR(10), PRIMARY KEY ("GroupCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCQG_GROUP_NAME" ON "TEST_AP"."OCQG" ( "GroupName" ASC )